// =============================================================================
// RESQFLY CONSOLE — TELEMETRY SERVICE (MAVLink Live Hardware & Cloud Sync)
// =============================================================================
// Connects to local Pixhawk serial bridge / cloud GCS / Web Serial postMessage.
// When live data is received, seamlessly switches from SIM to LIVE PIXHAWK telemetry.
// =============================================================================

import type { TelemetryData } from './types';

export class TelemetryService {
  data: TelemetryData;
  private startTime: number;
  private lastLivePacketTime: number = 0;

  constructor() {
    this.startTime = performance.now() / 1000;
    this.data = {
      alt: 0.0,
      alt_msl: 0.0,
      speed: 0.0,
      vspeed: 0.0,
      pitch: 0.0,
      roll: 0.0,
      yaw: 0.0,
      heading: 0.0,
      lat: 37.774921,
      lon: -122.419416,
      satellites: 18,
      gps_fix: '3D FIX',
      battery_pct: 100,
      volts: 22.2,
      amps: 0.0,
      battery_temp: 32.0,
      mah_drawn: 0,
      mode: 'STABILIZE',
      armed: false,
      rssi: -54,
      snr: 32.0,
      latency: 4,
      loss: 0.0,
      throttle: 0,
      link_source: 'PIXHAWK',
      is_live: true,
    };

    this.initListeners();
    this.startPolling();
  }

  private initListeners(): void {
    // 1. Listen for postMessage from parent React DroneTerminal window
    if (typeof window !== 'undefined') {
      window.addEventListener('message', (e) => {
        if (e.data && e.data.type === 'TELEMETRY_UPDATE' && e.data.data) {
          this.applyLiveTelemetry(e.data.data);
        }
      });
    }
  }

  private startPolling(): void {
    const fetchTelem = async () => {
      try {
        // Try local Pixhawk bridge first (0ms latency on laptop), then fallback to Vercel
        const endpoints = [
          'http://localhost:3000/api/drone/telemetry',
          'https://resqfly-backend.vercel.app/api/drone/telemetry'
        ];

        for (const ep of endpoints) {
          try {
            const res = await fetch(ep, { headers: { 'Accept': 'application/json' } });
            if (res.ok) {
              const json = await res.json();
              if (json?.data) {
                this.applyLiveTelemetry(json.data);
                break;
              }
            }
          } catch (err) {
            // try next endpoint
          }
        }
      } catch (err) {
        // network polling error
      }
    };

    fetchTelem();
    setInterval(fetchTelem, 500);
  }

  public applyLiveTelemetry(data: any): void {
    this.lastLivePacketTime = performance.now();
    this.data.is_live = true;
    this.data.link_source = data.droneId && data.droneId.includes('Pixhawk') ? 'PIXHAWK' : (data.link_source || 'PIXHAWK');

    if (data.flightMode) this.data.mode = data.flightMode;
    if (data.mode) this.data.mode = data.mode;
    if (data.altitude !== undefined) this.data.alt = +data.altitude;
    if (data.alt !== undefined) this.data.alt = +data.alt;
    this.data.alt_msl = this.data.alt;

    if (data.speed !== undefined) this.data.speed = +data.speed;
    if (data.battery !== undefined) this.data.battery_pct = +data.battery;
    if (data.battery_pct !== undefined) this.data.battery_pct = +data.battery_pct;
    if (data.voltage !== undefined && data.voltage > 0) this.data.volts = +data.voltage;
    if (data.volts !== undefined) this.data.volts = +data.volts;

    if (data.heading !== undefined) {
      this.data.heading = +data.heading;
      this.data.yaw = +data.heading;
    }
    if (data.pitch !== undefined) this.data.pitch = +data.pitch;
    if (data.roll !== undefined) this.data.roll = +data.roll;

    if (data.lat !== undefined && data.lat !== 0) this.data.lat = +data.lat;
    if (data.lon !== undefined && data.lon !== 0) this.data.lon = +data.lon;
    if (data.sats !== undefined) this.data.satellites = +data.sats;
    if (data.satellites !== undefined) this.data.satellites = +data.satellites;
    if (data.armed !== undefined) this.data.armed = Boolean(data.armed);
  }

  update(): void {
    const isLiveActive = (performance.now() - this.lastLivePacketTime) < 3000;
    
    if (isLiveActive) {
      this.data.is_live = true;
      return; // Do not overwrite real physical MAVLink telemetry with wave simulation!
    }

    // Only apply gentle micro-fluctuations if disconnected from Pixhawk
    const t = performance.now() / 1000 - this.startTime;
    this.data.pitch = Math.round(Math.sin(t * 1.5) * 1.5 * 10) / 10;
    this.data.roll = Math.round(Math.cos(t * 1.8) * 1.2 * 10) / 10;
  }
}
